/**
 * Small helpers reproducing the exact semantics of the Python `str` methods
 * the reference implementation relies on.
 */

/** Characters Python's `str.strip()` removes when called with no argument. */
const PY_WHITESPACE = new Set([
  '\t', '\n', '\v', '\f', '\r', ' ',
  '', '', '', '',
  '', ' ', ' ',
  ' ', ' ', ' ', ' ', ' ', ' ', ' ',
  ' ', ' ', ' ', ' ',
  ' ', ' ', ' ', ' ', '　',
]);

/** Equivalent of Python's `str.strip()` (no-argument form). */
export function pyStrip(text) {
  let start = 0;
  let end = text.length;
  while (start < end && PY_WHITESPACE.has(text[start])) start += 1;
  while (end > start && PY_WHITESPACE.has(text[end - 1])) end -= 1;
  return text.slice(start, end);
}

/** True when `ch` is a cased character (Lu / Ll / Lt), as Python defines it. */
function isCased(ch) {
  return ch.toLowerCase() !== ch.toUpperCase();
}

/**
 * Equivalent of Python's `str.title()`: the first cased character of every
 * run is upper-cased, every character following a cased one is lower-cased.
 * Non-cased characters (digits, apostrophes, spaces) reset the run.
 */
export function pyTitle(text) {
  let out = '';
  let previousCased = false;
  for (const ch of text) {
    if (previousCased) {
      out += ch.toLowerCase();
    } else {
      out += ch.toUpperCase();
    }
    previousCased = isCased(ch);
  }
  return out;
}

/** Python's `str.lower()`. */
export const pyLower = (text) => text.toLowerCase();

/** Python's `str.upper()`. */
export const pyUpper = (text) => text.toUpperCase();

