/**
 * Copies the capitalization pattern of `master` onto `disciple`.
 *
 *   'friend'  + 'enemies' -> 'enemies'   (all lower)
 *   'FRIEND'  + 'enemies' -> 'ENEMIES'   (all upper)
 *   'Friend'  + 'enemies' -> 'Enemies'   (title case)
 *   'fRiEnD'  + 'enemies' -> 'enemies'   (no recognizable pattern)
 *
 * A blank `master` carries no pattern, so `disciple` is returned untouched.
 */
export function matchCase(master, disciple) {
  if (!pyStrip(master)) {
    return disciple;
  }
  if (pyLower(master) === master) {
    return pyLower(disciple);
  }
  if (pyUpper(master) === master) {
    return pyUpper(disciple);
  }
  if (pyTitle(master) === master) {
    return pyTitle(disciple);
  }
  return disciple;
}

