import { irregularPluralOf, isIrregularPlural } from './irregulars.mjs';
import { matchCase } from './casematch.mjs';
import { pyStrip, pyLower } from './pystr.mjs';

const VOWELS = 'aeiou';

/**
 * Semi-intelligently converts an English *word* from singular to plural,
 * preserving the original capitalization pattern.
 *
 *   pluralize('friend') -> 'friends'
 *   pluralize('enemy')  -> 'enemies'
 *   pluralize('Sheep')  -> 'Sheep'
 *
 * Words that are blank or already a known irregular plural are handed back
 * exactly as they came in, spacing and odd casing included.
 */
export function pluralize(word) {
  const originalWord = word;
  const normalized = pyLower(pyStrip(word));

  if (!normalized || isIrregularPlural(normalized)) {
    return originalWord;
  }

  const irregularPlural = irregularPluralOf(normalized);
  if (irregularPlural) {
    return matchCase(originalWord, irregularPlural);
  }

  // `slice(-2, -1)` yields '' for one-character words; an empty string counts
  // as a vowel for `includes`, matching Python's `'' in 'aeiou'` being true.
  const beforeLast = normalized.slice(-2, -1);
  let pluralized;
  if (normalized.endsWith('y') && !VOWELS.includes(beforeLast)) {
    pluralized = `${normalized.slice(0, -1)}ies`;
  } else if (
    normalized.endsWith('s') ||
    normalized.endsWith('ch') ||
    normalized.endsWith('sh')
  ) {
    pluralized = normalized.endsWith('es') ? normalized : `${normalized}es`;
  } else {
    pluralized = `${normalized}s`;
  }

  return matchCase(originalWord, pluralized);
}

/**
 * Returns the singular form of *unit* when *count* is exactly 1, otherwise
 * the plural form.
 *
 *   cardinalize('vote', 1) -> 'vote'
 *   cardinalize('vote', 2) -> 'votes'
 */
export function cardinalize(unit, count) {
  if (count === 1) {
    return unit;
  }
  return pluralize(unit);
}

