import { cardinalize } from './inflection.mjs';

/**
 * Returns a plural noun phrase describing how many items a sized collection
 * holds.
 *
 *   unitLen([1, 2, 3], 'number') -> '3 numbers'
 *   unitLen([], 'string')        -> 'no strings'
 */
export function unitLen(sizedIterable, unitNoun = 'item') {
  const count = sizedIterable.length;
  const units = cardinalize(unitNoun, count);
  if (count) {
    return `${count} ${units}`;
  }
  return `no ${units}`;
}

