import { basename } from 'node:path';

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/**
 * Minimal re-implementation of the slice of Python's `argparse` that the
 * original script relies on: long options that each take exactly one value,
 * an automatic `-h/--help`, prefix abbreviation, `--opt=value` syntax, and
 * the same usage/error text and exit codes.
 */
export class ArgumentParser {
  constructor({ prog = defaultProg(), stdout = process.stdout, stderr = process.stderr } = {}) {
    this.prog = prog;
    this.stdout = stdout;
    this.stderr = stderr;
    this.actions = [
      { optionStrings: ['-h', '--help'], dest: 'help', isHelp: true, help: 'show this help message and exit' },
    ];
  }

  /** Registers a value-taking option, e.g. `addArgument('--a', {required: true})`. */
  addArgument(optionString, { required = false, help = '', metavar = null } = {}) {
    const dest = optionString.replace(/^-+/, '');
    this.actions.push({
      optionStrings: [optionString],
      dest,
      isHelp: false,
      required,
      help,
      metavar: metavar ?? dest.toUpperCase(),
    });
    return this;
  }

  /** `usage: prog [-h] --a A --b B` */
  formatUsage() {
    const parts = this.actions.map((action) => {
      const flag = action.optionStrings[0];
      return action.isHelp ? '[-h]' : `${flag} ${action.metavar}`;
    });
    return `usage: ${this.prog} ${parts.join(' ')}\n`;
  }

  formatHelp() {
    const invocations = this.actions.map((action) =>
      action.isHelp
        ? action.optionStrings.join(', ')
        : `${action.optionStrings[0]} ${action.metavar}`,
    );
    // argparse indents actions by 2 and puts help text at
    // min(longest invocation + indent + 2, 24).
    const indent = 2;
    const longest = Math.max(...invocations.map((text) => text.length + indent));
    const helpColumn = Math.min(longest + 2, 24);

    let out = `${this.formatUsage()}\noptions:\n`;
    invocations.forEach((invocation, index) => {
      const left = ' '.repeat(indent) + invocation;
      const helpText = this.actions[index].help;
      out += helpText
        ? `${left.padEnd(helpColumn, ' ')}${helpText}\n`
        : `${left}\n`;
    });
    return out;
  }

  /** Prints usage plus `prog: error: message` on stderr and exits with 2. */
  error(message) {
    this.stderr.write(this.formatUsage());
    this.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  /** Long/short option lookup with argparse's unambiguous-prefix matching. */
  #findAction(name) {
    const exact = this.actions.find((action) => action.optionStrings.includes(name));
    if (exact) {
      return { action: exact, matched: name };
    }
    if (!name.startsWith('--')) {
      return null;
    }
    const candidates = [];
    for (const action of this.actions) {
      for (const optionString of action.optionStrings) {
        if (optionString.startsWith(name)) {
          candidates.push({ action, matched: optionString });
        }
      }
    }
    if (candidates.length === 1) {
      return candidates[0];
    }
    if (candidates.length > 1) {
      const options = candidates.map((candidate) => candidate.matched).join(', ');
      this.error(`ambiguous option: ${name} could match ${options}`);
    }
    return null;
  }

  /** Mirrors argparse's `_parse_optional`: is this token an option or a value? */
  #looksLikeOption(token) {
    if (!token || !token.startsWith('-')) return false;
    if (this.actions.some((action) => action.optionStrings.includes(token))) return true;
    if (token.length === 1) return false; // a lone '-' is a value
    if (NEGATIVE_NUMBER.test(token)) return false; // no numeric-looking options exist
    if (token.includes(' ')) return false;
    return true;
  }

  /**
   * Parses `argv` (defaults to the command-line arguments) and returns an
   * object keyed by destination name.  Exits the process on `-h`/`--help`
   * and on any of argparse's error conditions.
   */
  parseArgs(argv = process.argv.slice(2)) {
    const values = Object.create(null);
    const seen = new Set();
    const extras = [];

    for (let index = 0; index < argv.length; index += 1) {
      const token = argv[index];

      if (token === '--') {
        // Everything from here on is positional; this parser defines none,
        // so the separator and the rest become unrecognized arguments.
        extras.push(...argv.slice(index));
        break;
      }

      if (!this.#looksLikeOption(token)) {
        extras.push(token);
        continue;
      }

      const equalsAt = token.startsWith('--') ? token.indexOf('=') : -1;
      const name = equalsAt === -1 ? token : token.slice(0, equalsAt);
      const inlineValue = equalsAt === -1 ? null : token.slice(equalsAt + 1);

      const match = this.#findAction(name);
      if (!match) {
        extras.push(token);
        continue;
      }

      const { action, matched } = match;
      if (action.isHelp) {
        this.stdout.write(this.formatHelp());
        process.exit(0);
      }

      let value = inlineValue;
      if (value === null) {
        const next = argv[index + 1];
        if (next === undefined || this.#looksLikeOption(next)) {
          this.error(`argument ${matched}: expected one argument`);
        }
        value = next;
        index += 1;
      }

      values[action.dest] = value;
      seen.add(action.dest);
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action.dest))
      .map((action) => action.optionStrings[0]);
    if (missing.length) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    if (extras.length) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return values;
  }
}

/** argparse defaults `prog` to the base name of the invoked script. */
export function defaultProg() {
  return basename(process.argv[1] ?? 'program');
}

